const item = $input.first().json;
const companyId = item.id || '';
const sourceUrl = item.career_page_url || '';

if (!sourceUrl) {
  return [{
    json: {
      company_id: companyId,
      is_valid: false,
      status: 'no_career_page_url',
      reason: 'Company has no career page URL'
    }
  }];
}

const response = await this.helpers.httpRequest({
  method: 'GET',
  url: sourceUrl,
  headers: {
    'User-Agent': 'Mozilla/5.0 (compatible; JobBot/1.0)'
  },
  returnFullResponse: false
});

const html = typeof response === 'string' ? response : JSON.stringify(response);

if (!html || html.length < 100) {
  return [{
    json: {
      company_id: companyId,
      is_valid: false,
      status: 'empty_response',
      reason: 'Career page returned empty or invalid HTML'
    }
  }];
}

const extractedJobs = [];

// 1. JSON-LD parsing
const jsonLdRegex = /<script\b[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
let match;
while ((match = jsonLdRegex.exec(html)) !== null) {
  try {
    const data = JSON.parse(match[1].trim());

    const processObject = (obj) => {
      if (obj && (obj['@type'] === 'JobPosting' || obj['type'] === 'JobPosting')) {
        const title = obj.title || obj.name;
        const description = obj.description || '';
        let location = '';
        if (obj.jobLocation) {
          if (typeof obj.jobLocation === 'string') {
            location = obj.jobLocation;
          } else if (obj.jobLocation.address) {
            const addr = obj.jobLocation.address;
            location = [addr.streetAddress, addr.addressLocality, addr.addressRegion, addr.postalCode, addr.addressCountry]
              .filter(Boolean).join(', ');
          }
        }
        if (title) {
          extractedJobs.push({
            company_id: companyId,
            title: title.trim(),
            description: description.trim() || `Open position for ${title.trim()}. See details at ${sourceUrl}`,
            location: location.trim() || 'Remote / Unspecified',
            job_type: 'Full-time',
            remote_type: location.toLowerCase().includes('remote') ? 'remote' : 'hybrid',
            currency: 'USD',
            application_url: (obj.url || sourceUrl).trim(),
            posted_at: obj.datePosted || null,
            is_valid: true
          });
        }
      }
    };

    if (Array.isArray(data)) data.forEach(processObject);
    else if (data['@graph'] && Array.isArray(data['@graph'])) data['@graph'].forEach(processObject);
    else processObject(data);
  } catch (e) {}
}

// 2. SAP SuccessFactors HTML table fallback
if (extractedJobs.length === 0) {
  const rowRegex = /<tr[^>]*class="data-row"[^>]*>([\s\S]*?)<\/tr>/gi;
  let rowMatch;

  while ((rowMatch = rowRegex.exec(html)) !== null) {
    const rowContent = rowMatch[1];

    const titleLinkMatch =
      /<a\s+href="([^"]+)"[^>]*class="jobTitle-link"[^>]*>([^<]+)<\/a>/i.exec(rowContent) ||
      /<a\s+[^>]*class="jobTitle-link"[^>]*href="([^"]+)"[^>]*>([^<]+)<\/a>/i.exec(rowContent);

    if (!titleLinkMatch) continue;

    const relativeUrl = titleLinkMatch[1];
    const title = titleLinkMatch[2].trim();

    // Build absolute application URL
    let appUrl = relativeUrl;
    if (relativeUrl.startsWith('/')) {
      try {
        const urlObj = new URL(sourceUrl);
        appUrl = urlObj.origin + relativeUrl;
      } catch (e) {
        appUrl = sourceUrl;
      }
    } else if (!relativeUrl.startsWith('http')) {
      appUrl = sourceUrl;
    }

    const locMatch = /<span[^>]*class="jobLocation"[^>]*>\s*([^<]+)\s*<\/span>/i.exec(rowContent);
    const location = locMatch ? locMatch[1].trim() : 'Remote / Unspecified';

    const dateMatch = /<span[^>]*class="jobDate"[^>]*>\s*([^<]+)\s*<\/span>/i.exec(rowContent);
    const postedAt = dateMatch ? dateMatch[1].trim() : null;

    // Fetch individual job page to get real description
    let description = `Open position for ${title}. See details at ${appUrl}`;
    try {
      const jobPageResponse = await this.helpers.httpRequest({
        method: 'GET',
        url: appUrl,
        headers: {
          'User-Agent': 'Mozilla/5.0 (compatible; JobBot/1.0)'
        },
        returnFullResponse: false
      });

      const jobHtml = typeof jobPageResponse === 'string' ? jobPageResponse : '';

      // SAP SuccessFactors job description is in .jobDescriptionContent or similar
      const descMatch =
        /<div[^>]*class="[^"]*jobDescriptionContent[^"]*"[^>]*>([\s\S]*?)<\/div>/i.exec(jobHtml) ||
        /<div[^>]*id="[^"]*jobDescription[^"]*"[^>]*>([\s\S]*?)<\/div>/i.exec(jobHtml) ||
        /<div[^>]*class="[^"]*job-description[^"]*"[^>]*>([\s\S]*?)<\/div>/i.exec(jobHtml) ||
        /<div[^>]*class="[^"]*description[^"]*"[^>]*>([\s\S]*?)<\/div>/i.exec(jobHtml);

      if (descMatch) {
        description = descMatch[1]
          .replace(/<[^>]*>/g, ' ')  // strip HTML tags
          .replace(/\s+/g, ' ')       // collapse whitespace
          .trim()
          .substring(0, 5000);        // cap at 5000 chars
      }
    } catch (e) {
      // Keep default description if job page fetch fails
    }

    if (title && title.length > 2 && title.length < 150) {
      extractedJobs.push({
        company_id: companyId,
        title: title,
        location: location,
        description: description,
        job_type: 'Full-time',
        remote_type: location.toLowerCase().includes('remote') ? 'remote' : 'hybrid',
        currency: 'USD',
        application_url: appUrl,        // ← now the individual job URL
        posted_at: postedAt,
        is_valid: true
      });
    }
  }
}

// 3. Generic HTML block fallback
if (extractedJobs.length === 0) {
  const blockRegex = /<(div|li|article|section)\b[^>]*class="[^"]*(?:job|vacancy|position|posting|listing|opportunity|career)[^"]*"[^>]*>([\s\S]*?)<\/\1>/gi;
  let blockMatch;

  while ((blockMatch = blockRegex.exec(html)) !== null) {
    const blockContent = blockMatch[2];

    let title = '';
    const hMatch = /<h[1-4]\b[^>]*>([\s\S]*?)<\/h[1-4]>/i.exec(blockContent);
    if (hMatch) {
      title = hMatch[1].replace(/<[^>]*>/g, '').trim();
    } else {
      const classTitleMatch = /<[^>]*class="[^"]*(?:title|position|role|job-name)[^"]*"[^>]*>([\s\S]*?)<\/[^>]+>/i.exec(blockContent);
      if (classTitleMatch) title = classTitleMatch[1].replace(/<[^>]*>/g, '').trim();
    }

    if (!title || title.length < 3 || title.length > 150) continue;

    const locMatch = /<[^>]*class="[^"]*(?:location|city|remote|country|place|region)[^"]*"[^>]*>([\s\S]*?)<\/[^>]+>/i.exec(blockContent);
    const location = locMatch ? locMatch[1].replace(/<[^>]*>/g, '').trim() : 'Remote / Unspecified';

    const linkRegex = /<a\b[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi;
    let linkMatch;
    let bestLink = '';
    while ((linkMatch = linkRegex.exec(blockContent)) !== null) {
      const href = linkMatch[1];
      const text = linkMatch[2].replace(/<[^>]*>/g, '').toLowerCase();
      if (text.includes('apply') || text.includes('view') || text.includes('detail') || href.includes('job') || href.includes('apply')) {
        bestLink = href;
        break;
      }
      if (!bestLink) bestLink = href;
    }

    let appUrl = sourceUrl;
    if (bestLink) {
      if (bestLink.startsWith('/')) {
        try {
          const urlObj = new URL(sourceUrl);
          appUrl = urlObj.origin + bestLink;
        } catch (e) {
          appUrl = sourceUrl;
        }
      } else if (bestLink.startsWith('http')) {
        appUrl = bestLink;
      }
    }

    extractedJobs.push({
      company_id: companyId,
      title: title,
      location: location,
      description: `Open position for ${title}. See details at ${appUrl}`,
      job_type: 'Full-time',
      remote_type: (location.toLowerCase().includes('remote') || title.toLowerCase().includes('remote')) ? 'remote' : 'hybrid',
      currency: 'USD',
      application_url: appUrl,
      posted_at: null,
      is_valid: true
    });
  }
}

// 4. Nothing found
if (extractedJobs.length === 0) {
  return [{
    json: {
      company_id: companyId,
      source_url: sourceUrl,
      is_valid: false,
      status: 'no_jobs_extracted',
      reason: 'Could not parse any jobs from the career page'
    }
  }];
}

return extractedJobs.map(job => ({ json: job }));
